import os
import sys
import hashlib
import subprocess

def escape_text(text):
    return text.replace('\t', '\\t').replace('\n', '\\n')

def compute_digest(prev_line, current_fields):
    concatenated = prev_line if prev_line else ''
    concatenated += '\t'.join(current_fields)
    return hashlib.sha256(concatenated.encode('utf-8')).hexdigest().lower()

def main():
    if len(sys.argv) != 3:
        sys.exit(1)

    commands_file = sys.argv[1]
    log_file = sys.argv[2]

    try:
        with open(log_file, 'a', encoding='utf-8') as f:
            prev_line = ''
            with open(commands_file, 'r', encoding='utf-8') as cmd_file:
                for line in cmd_file:
                    line = line.strip()
                    if not line:
                        continue

                    cmd = line
                    try:
                        result = subprocess.run(cmd, shell=True, check=False, text=True, capture_output=True)
                        exit_status = result.returncode
                        output = result.stdout + result.stderr
                    except FileNotFoundError:
                        exit_status = 127
                        output = str(sys.exc_info()[1])

                    escaped_cmd = escape_text(cmd)
                    escaped_output = escape_text(output)
                    digest = compute_digest(prev_line, [escaped_cmd, str(exit_status), escaped_output])

                    f.write(f"{escaped_cmd}\t{exit_status}\t{escaped_output}\t{digest}\n")
                    prev_line = f"{escaped_cmd}\t{exit_status}\t{escaped_output}\t{digest}\n"
    except IOError as e:
        print(f"{str(e)}", file=sys.stderr)
        sys.exit(1)

    sys.exit(0)

if __name__ == "__main__":
    main()

import os
import sys
import subprocess
import hashlib

def escape_special_chars(text):
    return text.replace('\n', '\\n').replace('\t', '\\t')

def compute_hash(prev_line):
    if not prev_line:
        data = b''
    else:
        data = prev_line.encode('utf-8')
    return hashlib.sha256(data).hexdigest()

def process_commands(commands_file, log_file):
    try:
        with open(log_file, 'a', encoding='utf-8') as f:
            with open(commands_file, 'r', encoding='utf-8') as cmd_file:
                prev_line = ''
                for line in cmd_file:
                    line = line.strip()
                    if not line:
                        continue
                    cmd = line
                    try:
                        result = subprocess.run(cmd, shell=True, check=True,
                                              stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                                              text=True)
                        output = result.stdout + result.stderr
                    except subprocess.CalledProcessError as e:
                        output = e.stderr if hasattr(e, 'stderr') else str(e)
                        result = e
                    except Exception:
                        output = str(sys.exc_info()[1])
                        result = None

                    escaped_cmd = escape_special_chars(cmd)
                    escaped_output = escape_special_chars(output)
                    status = str(result.returncode) if result else '127'
                    hex_digest = compute_hash(prev_line + '\n' + escaped_cmd + '\t' + status + '\t' + escaped_output)

                    f.write(f"{escaped_cmd}\t{status}\t{escaped_output}\t{hex_digest}\n")
                    prev_line = f"{escaped_cmd}\t{status}\t{escaped_output}\t{hex_digest}\n"
    except IOError as e:
        print(str(e) + '\n', file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python3 runlog.py <commands_file> <log_file>", file=sys.stderr)
        sys.exit(1)
    process_commands(sys.argv[1], sys.argv[2])
    sys.exit(0)

