import sys
import os
import subprocess
import hashlib

def escape_special_chars(text):
    return text.replace('\n', '\\n').replace('\t', '\\t')

def process_commands(commands_file, log_file):
    try:
        with open(commands_file, 'r', encoding='utf-8') as cmd_f:
            commands = [line.strip() for line in cmd_f if line.strip()]
    except IOError as e:
        print(f"Error reading commands file: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        with open(log_file, 'a', encoding='utf-8') as log_f:
            for cmd in commands:
                try:
                    result = subprocess.run(cmd, shell=True, check=False, text=True, capture_output=True)
                    exit_status = result.returncode
                    output = result.stdout + result.stderr
                except FileNotFoundError:
                    exit_status = 127
                    output = str(e)

                escaped_cmd = escape_special_chars(cmd)
                escaped_output = escape_special_chars(output)
                cmd_hash = hashlib.sha256(escaped_cmd.encode('utf-8')).hexdigest().lower()

                log_entry = f"{escaped_cmd}\t{exit_status}\t{escaped_output}\t{cmd_hash}\t{exit_status}"
                log_f.write(log_entry + '\n')
    except IOError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python3 runlog.py <commands_file> <log_file>", file=sys.stderr)
        sys.exit(1)

    process_commands(sys.argv[1], sys.argv[2])
    sys.exit(0)
